-- Schema for the synthetic portfolio datasets (SQLite dialect).
-- Load with:  sqlite3 portfolio.db < data/seed_sqlite.sql   (the seed file includes this schema)
-- ALL DATA IS FICTIONAL. Generated by scripts/export-seed-data.ts from fixed seeds.

-- ===== AML lab =====
CREATE TABLE customer (
  customer_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  customer_type TEXT NOT NULL,              -- individual | business
  segment TEXT NOT NULL,                    -- retail | small_business | commercial
  activity TEXT NOT NULL,                   -- declared occupation / business activity (KYC)
  account_purpose TEXT NOT NULL,
  declared_monthly_turnover REAL NOT NULL,  -- CAD, declared at onboarding/review
  expected_monthly_tx_count INTEGER NOT NULL,
  international_expected INTEGER NOT NULL,  -- 0/1
  account_id TEXT NOT NULL,
  account_opened TEXT NOT NULL,
  kyc_status TEXT NOT NULL,                 -- verified | refresh_due | incomplete
  kyc_last_review TEXT NOT NULL,
  risk_rating TEXT NOT NULL                 -- low | medium | high (product/channel factors only)
);

CREATE TABLE txn (
  tx_id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES customer(customer_id),
  account_id TEXT NOT NULL,
  tx_date TEXT NOT NULL,
  amount REAL NOT NULL CHECK (amount > 0),
  direction TEXT NOT NULL,                  -- credit | debit
  channel TEXT NOT NULL,                    -- eft | wire_domestic | wire_international | cash | card | internal
  counterparty TEXT NOT NULL,
  counterparty_country TEXT NOT NULL,
  reference TEXT NOT NULL,
  branch TEXT,
  source_system TEXT NOT NULL,              -- CORE_LIVE | MIGRATED_LEDGER
  migration_batch TEXT,
  load_run INTEGER
);

CREATE TABLE erp_document (
  reference TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  erp_amount REAL NOT NULL,
  erp_doc_id TEXT NOT NULL
);

-- ===== Reconciliation lab =====
CREATE TABLE legacy_extract (
  src_id TEXT PRIMARY KEY,
  extract_row INTEGER NOT NULL,
  posting_date TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  segment TEXT NOT NULL,                    -- RT | SB | CM
  reference TEXT NOT NULL,
  amount REAL NOT NULL,
  description TEXT
);

CREATE TABLE erp_gl_entry (
  je_id TEXT PRIMARY KEY,
  posting_date TEXT NOT NULL,
  gl_account TEXT NOT NULL,
  reference TEXT NOT NULL,
  amount REAL NOT NULL,
  customer_id TEXT,
  migration_batch TEXT,
  load_run INTEGER,
  staging_row_id TEXT,
  entry_type TEXT NOT NULL,                 -- MIGRATED | MANUAL_JOURNAL | CORRECTION
  status TEXT NOT NULL,                     -- POSTED | REVERSED
  description TEXT
);

CREATE TABLE gl_mapping (segment TEXT PRIMARY KEY, gl_account TEXT NOT NULL, gl_name TEXT NOT NULL);

CREATE TABLE staging_log (
  staging_row_id TEXT PRIMARY KEY,
  src_id TEXT NOT NULL,
  extract_row INTEGER NOT NULL,
  mapping_version TEXT NOT NULL,
  load_status TEXT NOT NULL,                -- LOADED | REJECTED
  reject_reason TEXT,
  load_runs TEXT                            -- comma-separated run numbers
);

-- ===== Data engineering lab (star schema output) =====
CREATE TABLE dim_customer (customer_key TEXT PRIMARY KEY, name TEXT, segment TEXT, region TEXT);
CREATE TABLE fact_payment (
  payment_key TEXT PRIMARY KEY,
  date_key TEXT NOT NULL,
  month TEXT NOT NULL,
  customer_key TEXT REFERENCES dim_customer(customer_key),
  channel TEXT NOT NULL,
  currency TEXT NOT NULL,
  amount_original REAL NOT NULL,
  fx_rate REAL,
  amount_cad REAL,
  natural_key TEXT NOT NULL,
  lineage_raw_ids TEXT NOT NULL
);
